        K.eq([(e["id"], e["config"], e["replaces"]) for e in ms["modules"]], [("bank", ["SkyyBank"], ["SkyyBank"])],
             "ASM fix2: a merge module taking over SkyyBank's section (MOD SkyyBank, REPLACES SkyyBank) is accepted")
        K.eq(B.jar_config_sections(_js), [("com.skyy.asmtest.bank", "SkyyBank")], "ASM fix2: jar_config_sections reads the module's MOD")
        cf = XCK.config_fails(bank + [("SkyyAsmTest", "0.1.0", _js)])
