    open(vb, "w", encoding="utf8").write(BETA.replace('VERSION = "0.1.0"', 'VERSION = "0.2.0"'))
    refused("ASM: jar 1.0.0 again with beta 0.2.0", "already assembled from DIFFERENT modules", [os.path.join(md, "alpha.py"), vb],
            ver="1.0.0", here=vdir)
    J4 = fresh()
    c4 = B.link_core(J4["pool"], version=VERSION)
    _j, m4 = B.assemble_modules(J4, "SkyyAsmTest", "auto", [os.path.join(md, "alpha.py"), vb], "x", vdir, core=c4)
    K.eq(m4["version"], "1.0.1", "ASM: 'auto' after a module changed = 1.0.1 (the jar version bumped by the assemble step)")
