# =====================================================================================================================  JVM helpers
def boot(cp=()):
    from jpype import JClass
    HK.jvm([B.SERVER_JAR, B.JAVASSIST] + list(cp), verify=True)
    srv = JClass("java.lang.ClassLoader").getSystemClassLoader()

    def ldr(path, parent):
        URL = JClass("java.net.URL")
        import jpype
        return JClass("java.net.URLClassLoader")(jpype.JArray(URL)([JClass("java.io.File")(path).toURI().toURL()]), parent)
    core_l = ldr(JAR, srv)
    return srv, core_l, ldr


def jarnames(p):
    return sorted(n[:-6].replace("/", ".") for n in zipfile.ZipFile(p).namelist() if n.endswith(".class"))


# =====================================================================================================================  A
def run_verify_core(out, jar, scratch, _home):
    from jpype import JClass
    K = HK.Child(out)
    srv, CL, ldr = boot()
    Cls = JClass("java.lang.Class")
    args = [str(x) for x in JClass("java.lang.management.ManagementFactory").getRuntimeMXBean().getInputArguments()]
    K.check("-Xverify:all" in args, "A: the JVM runs with -Xverify:all")
    got = {}
    for n in jarnames(JAR):
        try:
            c = Cls.forName(n, False, CL)
            c.getDeclaredMethods(); c.getDeclaredFields(); c.getDeclaredConstructors()
            got[n] = c
        except Exception as e:
            K.check(False, "A: verify %s: %s" % (n, str(e)[:300]))
    for n, c in got.items():
        try:
            Cls.forName(n, True, CL)
        except Exception as e:
            K.check(False, "A: init %s: %s" % (n, str(e)[:300]))
    K.check(len(got) == 16, "A: %d Core classes loaded + verified + initialised in Core's own loader" % len(got))
    Sys = JClass("java.lang.System")
    Sys.getProperties().remove("skyy.bridge")
    R = JClass("com.skyy.core.cfg.CfgRows", loader=CL)
    K.check(R.DC is None and str(R.MOD) == "" and len(R.KEYS) == 0 and len(R.FILES) == 0 and str(R.HOMEDIR) == "Skyy_",
            "A: the template in Core's own loader has no mod data (DC null, no rows, no files)")
    tmp = os.path.join(scratch, "tpl_mods")
    os.makedirs(tmp, exist_ok=True)
    JClass("com.skyy.core.cfg.CfgPub", loader=CL).start(JClass("java.nio.file.Paths").get(tmp), None)
    br = Sys.getProperties().get("skyy.bridge")
    keys = [] if br is None else [str(k) for k in br.keySet() if str(k).startswith("config:")]
    K.eq(keys, [], "A: CfgPub.start on the bare template publishes nothing")
    K.eq(os.listdir(tmp), [], "A: ... and writes nothing")
    K.save()


# =====================================================================================================================  API
def run_api(out, jar, scratch, _home):
    import jpype
    from jpype import JClass, JImplements, JOverride, JArray, JObject
    K = HK.Child(out)
    srv, CL, ldr = boot()
    TL = ldr(SAMPLE, CL)
    Sys = JClass("java.lang.System")
    Sys.getProperties().remove("skyy.bridge")
    C = lambda n: JClass(n, loader=CL)
    T = lambda n: JClass(n, loader=TL)
    Core, KL, Cfg, Txt, HB, Ui, MV = (C("com.skyy.core.Core"), C("com.skyy.core.KitLoader"), C("com.skyy.core.cfg.Cfg"),
                                      C("com.skyy.core.cfg.CfgText"), C("com.skyy.core.ui.HubBar"), C("com.skyy.core.ui.UiKit"),
                                      C("com.skyy.core.move.MoveSync"))
    UUID, Paths, Files = JClass("java.util.UUID"), JClass("java.nio.file.Paths"), JClass("java.nio.file.Files")
    ih = lambda o: int(Sys.identityHashCode(o))
    A = UUID.fromString(A_UUID)

    @JImplements("java.util.function.Function")
    class Fn(object):
        def __init__(self, f):
            self.f = f

        @JOverride
        def apply(self, x):
            return self.f(x)

    def boom(x):
        raise RuntimeError("boom on purpose")
    # ---------------------------------------------------------------- Core
    K.eq(str(Core.version()), VERSION, "Core.version()")
    K.check(Sys.getProperties().get("skyy.bridge") is None, "no bridge before the first call")
    m = Core.bridge()
    K.check(ih(m) == ih(Sys.getProperties().get("skyy.bridge")) and ih(Core.BRIDGE) == ih(m) and ih(Core.bridge()) == ih(m),
            "Core.bridge() creates the System property map, caches it, same identity")
    K.check(bool(Core.put("k1", "v1")) and str(Core.get("k1")) == "v1", "put / get")
    K.check(not bool(Core.put(None, "x")) and Core.get(None) is None, "put / get with a null key answer, never throw")
    K.check(bool(Core.put("k1", None)) and Core.get("k1") is None, "put(k, null) removes")
    K.check(Core.putIfAbsent("k2", "a") is None and str(Core.putIfAbsent("k2", "b")) == "a" and str(Core.get("k2")) == "a", "putIfAbsent")
    K.check(not bool(Core.remove("k2", "b")) and bool(Core.remove("k2", "a")) and Core.get("k2") is None, "remove(k, v) only while it holds v")
    Core.put("f:ok", Fn(lambda x: "got " + str(x)))
    Core.put("f:boom", Fn(boom))
    Core.put("f:no", "not a function")
    K.check(str(Core.call("f:ok", "z")) == "got z" and Core.call("f:boom", "z") is None and Core.call("f:no", "z") is None
            and Core.call("f:none", "z") is None, "call: answers, never throws")
    # fix round: fn(key) = a never-null SafeFn handle whose apply never throws (spec 2.1 "Core.fn(key).apply(...)")
    h_ok, h_boom, h_no, h_none = Core.fn("f:ok"), Core.fn("f:boom"), Core.fn("f:no"), Core.fn("f:late")
    K.check(all(h is not None for h in (h_ok, h_boom, h_no, h_none)), "fn: never null (also for an absent key)")
    K.check(str(h_ok.apply("z")) == "got z" and h_boom.apply("z") is None and h_no.apply("z") is None and h_none.apply("z") is None
            and Core.fn(None).apply("z") is None, "fn(key).apply: the answer, or null when absent / not a Function / it throws")
    K.check(bool(Core.has("f:ok")) and not bool(Core.has("f:no")) and not bool(Core.has("f:late")) and not bool(Core.has(None))
            and bool(h_ok.live()) and not bool(h_none.live()), "has(key) / handle.live(): a Function is published")
    Core.put("f:late", Fn(lambda x: "late " + str(x)))
    K.check(str(h_none.apply("z")) == "late z" and bool(h_none.live()), "fn handle: a publisher that starts later is found")
    Core.put("f:late", None)
    K.check(h_none.apply("z") is None and not bool(h_none.live()), "fn handle: a publisher that stops is let go")
    K.eq(str(Core.pkey(A)), A_UUID, "pkey without SkyyProfiles = the UUID (profile 1)")
    for v, want, what in (("abc-p2", "abc-p2", "a profile key"), ("", A_UUID, "an empty answer"), (None, A_UUID, "null")):
        Core.put("profile:fn:key", Fn(lambda x, v=v: v))
        K.eq(str(Core.pkey(A)), want, "pkey with profile:fn:key answering %s" % what)
    Core.put("profile:fn:key", Fn(boom))
    K.eq(str(Core.pkey(A)), A_UUID, "pkey with a throwing profile:fn:key = the UUID")
    Core.put("profile:fn:key", "junk")
    K.eq(str(Core.pkey(A)), A_UUID, "pkey with a non-Function = the UUID")
    Core.put("profile:fn:key", None)
    Core.register("SkyyT", "0.1", None)
    Core.register("SkyyA", "2.0", JClass("com.hypixel.hytale.logger.HytaleLogger").get("SkyyA"))
    K.eq(str(Core.modules()), "SkyyA 2.0, SkyyT 0.1", "register / modules()")
    Core.unregister("SkyyT")
    K.eq(str(Core.modules()), "SkyyA 2.0", "unregister")
    Core.say("SkyyA", True, "a warning through SkyyA's logger")
    Core.say(None, False, "no logger: silent")
    Core.warnMove("SkyyA: move warning")
    K.eq(str(Core.readyLine("SkyyBank", "0.1.14", "page abc")), "[SkyyBank] 0.1.14 ready - page abc", "readyLine with detail")
    K.eq(str(Core.readyLine("SkyyX", "1.0.0", "")), "[SkyyX] 1.0.0 ready", "readyLine without detail")
    Core.ready("SkyyX", "1.0.0", "x", None)
    sc = str(Core.selfCheck())
    K.check("config kit template 7/7" in sc and "Sky Window art 59/59" in sc and "MoveSync v1" in sc, "selfCheck: %s" % sc)
    # ---------------------------------------------------------------- KitLoader
    import skyycfg as CFG
    K.eq([str(x) for x in KL.NAMES], list(CFG.CORE_TEMPLATE), "KitLoader.NAMES = the 7 template classes")
    with zipfile.ZipFile(JAR) as z:
        for n in CFG.CORE_TEMPLATE:
            K.check(bytes(KL.bytesOf(n)) == z.read(n.replace(".", "/") + ".class"), "bytesOf(%s) = the jar's bytes" % n.rsplit(".", 1)[1])
    K.check(KL.isKit("com.skyy.core.cfg.CfgFn") and not KL.isKit("com.skyy.core.cfg.Cfg") and not KL.isKit(None), "isKit")
    K.check(KL.dataOf(JClass("java.lang.String").class_) is None and KL.dataOf(None) is None, "dataOf outside a KitLoader = null")
    # ---------------------------------------------------------------- Cfg
    dead = Cfg.open(None)
    K.check(not bool(dead.ok()) and "internal error" in str(dead.cmdSet("a", "b", A, "x")) and dead.cmdGet("a") is None
            and dead.op(JArray(JObject)([JObject("get", JClass("java.lang.String")), JObject("a", JClass("java.lang.String"))])) is None
            and len(dead.files()) == 0 and len(dead.histList(0)) == 0 and not bool(dead.prepare(None, None)) and "NOT loaded" in str(dead.status()),
            "Cfg.open(null): a dead handle that answers and never throws")
    dead.start(Paths.get(scratch), None)
    dead.shutdown()
    D1, D2 = T("com.skyy.coret.CfgData"), T("com.skyy.coret2.CfgData")
    h1 = D1.kit()
    K.check(bool(h1.ok()) and str(h1.mod()) == "SkyyCoreT" and ih(h1) == ih(Cfg.open(D1.class_)) and ih(h1) == ih(D1.kit()),
            "CfgData.kit() = Cfg.open(CfgData) = one handle (%s)" % h1.status())
    K.eq(str(h1.status()), "SkyyCoreT: config kit 1.1 from SkyyCore 1.0.1", "status()")
    L1 = h1.loader()
    K.check(str(L1.getClass().getName()) == "com.skyy.core.KitLoader" and ih(L1.getParent()) == ih(TL) and int(L1.defined) == 7,
            "the KitLoader = a child of the MODULE's loader; it defined the 7 kit classes")
    R1 = h1.kitClass("CfgRows")
    K.check(ih(R1.getClassLoader()) == ih(L1) and list(R1.getField("KEYS").get(None)) == list(D1.KEYS)
            and str(R1.getField("MOD").get(None)) == "SkyyCoreT" and int(R1.getField("KEEP").get(None)) == 10,
            "the kit copy reads the module's data (KEYS, MOD, KEEP)")
    h2 = D2.kit()
    R2 = h2.kitClass("CfgRows")
    K.check(bool(h2.ok()) and ih(R2) != ih(R1) and str(R2.getField("MOD").get(None)) == "SkyyCoreU"
            and str(R2.getField("HOMEDIR").get(None)) == "Skyy_SkyyCoreGroup/u" and list(R2.getField("KEYS").get(None)) == ["u.n"],
            "a second module = a second private kit copy (own MOD, HOMEDIR, rows; HOLDERS joined)")
    T("com.skyy.coret.TestPerm").OK.add(A)
    mods = os.path.join(scratch, "api_mods")
    os.makedirs(mods)
    pmods = Paths.get(mods)
    h1.start(pmods, None)
    h2.start(pmods, None)
    br = Core.bridge()
    hd = br.get("config:def:SkyyCoreT")
    K.check(hd is not None and len(hd) == 10 and str(hd[1]) == "SkyyCoreT" and str(hd[3]) == "0.1" and len(hd[7]) == 3,
            "start: config:def:SkyyCoreT = the header (contract, MOD, TITLE, VERSION, ..., 3 rows)")
    K.check(JClass("java.util.function.Function").class_.isInstance(br.get("config:fn:SkyyCoreT"))
            and JClass("java.lang.Long").class_.isInstance(br.get("config:epoch:SkyyCoreT"))
            and br.get("config:def:SkyyCoreU") is not None, "start: config:fn / config:epoch published; the second module too")
    TC = T("com.skyy.coret.TestCfg")
    r = str(h1.cmdSet("t.limit", "7", A, "Skyy"))
    K.check(int(TC.LIMIT) == 7 and "7" in r, "cmdSet through the kit copy (permission hook) -> the field (%s)" % r)
    B_ = UUID.fromString("00000000-0000-0000-0000-00000000000b")
    r = str(h1.cmdSet("t.limit", "9", B_, "Other"))
    K.check(int(TC.LIMIT) == 7, "cmdSet by a player without the node is refused (%s)" % r)
    K.eq(str(h1.cmdGet("t.limit")), "7", "cmdGet")
    K.check(h1.cmdGet("nope") is None, "cmdGet of an unknown key = null")
    K.eq(str(h1.op(JArray(JObject)([JObject("get", JClass("java.lang.String")), JObject("t.limit", JClass("java.lang.String"))]))), "7",
         "op(get) = the config:fn path SkyyMenu uses")
    r = str(h1.cmdSetConsole("t.name", "Banana"))
    K.check(str(TC.NAME) == "Banana", "cmdSetConsole (%s)" % r)
    r = str(h1.cmdSet("t.items", "Rock_Stone", A, "Skyy"))
    K.check("Rock_Stone" in str(h1.cmdGet("t.items")), "items row through the item hook (%s)" % r)
    h1.flush()
    cfgp = os.path.join(mods, "Skyy_SkyyCoreT", "config.properties")
    txt = open(cfgp, encoding="latin-1").read() if os.path.isfile(cfgp) else ""
    K.check("limit=7" in txt and "name=Banana" in txt, "flush: Skyy_SkyyCoreT/config.properties holds the changes")
    K.check(os.path.isfile(os.path.join(mods, "Skyy_SkyyCoreT", "config-changes.log")), "the change log in the module's HOME")
    r = str(h2.cmdSet("u.n", "4", A, "Skyy"))
    h2.flush()
    K.check(int(T("com.skyy.coret2.U2Cfg").N) == 4 and os.path.isfile(os.path.join(mods, "Skyy_SkyyCoreGroup", "u", "config-changes.log"))
            and os.path.isfile(os.path.join(mods, "Skyy_SkyyCoreGroup", "u", "config.properties"))
            and not os.path.isdir(os.path.join(mods, "Skyy_SkyyCoreU")), "HOME override: the second module's files + log in Skyy_SkyyCoreGroup/u (%s)" % r)
    # the migration helpers (PROJECT-RULES 4 one-time migrations)
    home = os.path.join(mods, "Skyy_SkyyCoreT")
    K.check(bool(h1.prepare(Paths.get(home), None)), "prepare(home)")
    K.eq([str(x) for x in h1.files()], ["Skyy_SkyyCoreT/config.properties"], "files()")
    K.eq(str(h1.histDir()), os.path.join(home, "config-history"), "histDir()")
    st = str(h1.histStamp())
    K.check(len(st) == 19 and st[8] == "-", "histStamp() %s" % st)
    old_b = b"limit=1\nname=old\n"
    old = JArray(jpype.JByte)(old_b)
    n0 = len(h1.histList(0))
    h1.histSnapshot(0, old, st, "Test migration", "before a test migration")
    hl = [str(x) for x in h1.histList(0)]
    K.check(len(hl) == n0 + 1, "histSnapshot: one more history copy (%d -> %d)" % (n0, len(hl)))
    K.check(any(bytes(Files.readAllBytes(h1.histBak(0, s_))) == old_b for s_ in hl),
            "histList + histBak read the copy back byte for byte")
    line = str(Txt.now()) + "\tTest migration\t-\tupdate\tt.limit\t1\t7\tok"
    h1.logEnqueue(line)
    h1.logFlush()
    K.check(line in open(os.path.join(home, "config-changes.log"), encoding="utf-8").read(), "logEnqueue + logFlush: the change-log line")
    h1.shutdown()
    K.check(Cfg.OPEN.get(D1.class_) is None, "shutdown() releases the handle")
    # ---------------------------------------------------------------- CfgText = the classic kit's helpers
    CF, CR, CLg = (T("com.skyy.coretclassic.CfgFile"), T("com.skyy.coretclassic.CfgRows"), T("com.skyy.coretclassic.CfgLog"))
    AL = JClass("java.util.ArrayList")
    diffs = []
    for s in CORPUS:
        for nm in ("lead", "isComment", "cont", "keyEnd", "valStart", "unesc", "key"):
            a_, b_ = getattr(Txt, nm)(s), getattr(CF, nm)(s)
            if str(a_) != str(b_):
                diffs.append("%s(%r): %s vs %s" % (nm, s, a_, b_))
        for kk in (True, False):
            if str(Txt.esc(s, kk)) != str(CF.esc(s, kk)):
                diffs.append("esc(%r)" % s)
        if str(Txt.clip(s, 5)) != str(CR.clip(s, 5)) or str(Txt.oneLine(s + "\t\n")) != str(CR.oneLine(s + "\t\n")):
            diffs.append("clip / oneLine %r" % s)
        for t in ("level", "a", "g key"):
            if bool(Txt.isTemplate(s, t)) != bool(CF.isTemplate(s, t)):
                diffs.append("isTemplate(%r, %r)" % (s, t))
    text = "\n".join(CORPUS) + "\n"
    la, lb = Txt.split(text), CF.split(text)
    K.check([str(x) for x in la] == [str(x) for x in lb], "split")
    K.check(str(Txt.join(la, "\r\n", True)) == str(CF.join(lb, "\r\n", True)), "join")
    for k in range(len(la)):
        if int(Txt.end(la, k)) != int(CF.end(lb, k)) or str(Txt.value(la, k)) != str(CF.value(lb, k)):
            diffs.append("end / value at %d" % k)
    pa, pb = Txt.parseVals(la), CF.parseVals(lb)
    K.check(dict((str(e.getKey()), str(e.getValue())) for e in pa.entrySet()) == dict((str(e.getKey()), str(e.getValue())) for e in pb.entrySet()),
            "parseVals")
    for fk, val in (("a", "9"), ("new.key", "x y"), ("e", None), ("level", "4")):
        a2, b2 = AL(la), AL(lb)
        Txt.applyEdit(a2, fk, val)
        CF.applyEdit(b2, fk, val)
        if [str(x) for x in a2] != [str(x) for x in b2]:
            diffs.append("applyEdit %s" % fk)
    K.eq(diffs, [], "CfgText = the classic kit's CfgFile / CfgRows helpers on %d lines" % len(CORPUS))
    pa_, pb_ = os.path.join(scratch, "aw_core.txt"), os.path.join(scratch, "aw_classic.txt")
    data = JArray(jpype.JByte)(b"x=1\r\ny=2\n")
    Txt.atomicWrite(Paths.get(pa_), data)
    CR.atomicWrite(Paths.get(pb_), data)
    K.check(open(pa_, "rb").read() == open(pb_, "rb").read() == b"x=1\r\ny=2\n" and not os.path.exists(pa_ + ".tmp"),
            "atomicWrite: same bytes, no .tmp left")
    import re as _re
    K.check(_re.match(r"^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d$", str(Txt.now())) is not None and len(str(CLg.now())) == len(str(Txt.now())),
            "now() = the change-log time format")
    # ---------------------------------------------------------------- HubBar = the per-mod HubBar (+ the OWNER rule)
    HC = T("com.skyy.coretclassic.HubBar")
    UCB = JClass("com.hypixel.hytale.server.core.ui.builder.UICommandBuilder")
    UEB = JClass("com.hypixel.hytale.server.core.ui.builder.UIEventBuilder")
    TRUE, FALSE = JClass("java.lang.Boolean").TRUE, JClass("java.lang.Boolean").FALSE
    seen = []

    def scen(H, owner_core):
        Core.bridge().clear()
        seen[:] = []
        u = UUID.randomUUID()
        mm = H.map()
        mm.put("hub:last:" + str(u), JClass("java.util.concurrent.ConcurrentHashMap")())
        rec = []
        for t, o, mod, lab, cmd, op, vis in (("skills", 10, "SkyySkills", "Skills", "skills", "f", None),
                                              ("stats", 20, "SkyySkills", "Stats", "stats", "f", None),
                                              ("trees", 30, "SkyyTrees", "Trees", "trees", None, None),
                                              ("class", 40, "SkyyClasses", "Class", "class", "boom", None),
                                              ("pets", 50, "SkyyPets", "Pets", "pets", "f", "no"),
                                              ("coll", 60, "SkyyCollections", "Collections", "coll", "f", "yes")):
            opf = Fn(lambda x, t=t: (seen.append(t), TRUE)[1]) if op == "f" else (Fn(boom) if op == "boom" else None)
            vf = Fn(lambda x: FALSE) if vis == "no" else (Fn(lambda x: TRUE) if vis == "yes" else None)
            arr = H.put("character", t, mod, lab, o, cmd, opf, vf)
            rec.append(arr is not None)
        ucb, ueb = UCB(), UEB()
        n = H.build(ucb, ueb, "SkyyTP", "character", "skills", 960, u, 3)
        cmds = [(str(c.selector), str(c.text if c.text is not None else c.data)) for c in ucb.getCommands()]
        evs = [(str(x.selector), str(x.data)) for x in ueb.getEvents()]
        js = lambda a: '{"a":"%s"}' % a
        ans = [str(H.handle(None, js(a), "character", "skills")) for a in ("hub:close", "hub:back", "hub:skills", "hub:Nope", "hub:stats")]
        ans.append(H.handle(None, js("refresh"), "character", "skills"))
        ans += [str(H.open(None, u, "character", t)) for t in ("stats", "trees", "class", "pets", "nothere")]
        tabs = [str(x[0]) for x in H.tabs("character", u)]
        last = str(mm.get("hub:last:" + str(u)).get("character"))
        return rec, n, cmds, evs, ans, tabs, last, list(seen)
    a_core, a_classic = scen(HB, True), scen(HC, False)
    K.check(a_core == a_classic and a_core[1] == 5, "HubBar (Core) = the per-mod HubBar: same puts, build() commands + events, "
            "handle / open answers, tabs, hub:last (%d tabs, %d commands)" % (a_core[1], len(a_core[2])))
    Core.bridge().clear()
    mm = HB.map()
    for t, mod in (("bank", "SkyyBank"), ("vault", "SkyyVault"), ("sacks", "SkyySacks")):
        HB.put("storage", t, mod, t.title(), 10, t, None, None)
    getattr(HB, "def_")("SkyyMenu", "storage", "Storage", "storage", "")
    K.check(mm.get("hub:def:storage") is not None and HB.mine("SkyyMenu").size() == 1 and HB.mine("SkyyBank").size() == 1,
            "OWNER: put files a tab under its mod; def under its owner")
    K.eq(int(HB.removeAll("SkyyVault")), 1, "OWNER: removeAll(SkyyVault) removes its one tab")
    K.check(mm.get("hub:tab:storage:vault") is None and mm.get("hub:tab:storage:bank") is not None and mm.get("hub:tab:storage:sacks") is not None
            and mm.get("hub:def:storage") is not None, "OWNER: the other mods' tabs and SkyyMenu's def stay")
    mm.put("hub:tab:storage:bank", JArray(JObject)(6))
    K.eq(int(HB.removeAll("SkyyBank")), 0, "OWNER: a key another jar replaced is left alone")
    K.check(mm.get("hub:tab:storage:bank") is not None, "OWNER: the replacing array stays")
    K.eq(int(HB.removeAll("SkyyMenu")), 1, "OWNER: removeAll(SkyyMenu) removes its def")
    K.eq(int(HB.removeAll("SkyyNobody")), 0, "OWNER: an owner with nothing = 0")
    K.eq(int(HB.removeAll(None)), 0, "OWNER: removeAll(null) = 0, never throws")
    # ---------------------------------------------------------------- UiKit = the per-mod methods
    U2 = T("com.skyy.coretclassic.Ui")
    probe = ["+done", "-bad", "=info", "plain", "", None, "+", "x+"]
    K.check(all(str(Ui.colorOf(p)) == str(U2.colorOf(p)) and str(Ui.textOf(p)) == str(U2.textOf(p)) for p in probe),
            "UiKit.colorOf / textOf = the per-mod methods")
    gs = Ui.gridSlots(JArray(jpype.JString)([None, "", None]), None, 3)
    K.check(int(gs.size()) == 3 and str(Ui.gridSlot(None, 1).getClass().getName()).endswith("ItemGridSlot"), "UiKit.gridSlots / gridSlot (empty slots)")
    try:
        g = Ui.gridSlot("Rock_Stone", 2)
        K.check(g is not None, "UiKit.gridSlot(id, qty) builds a slot")
    except Exception as e:
        K.notes.append("UiKit.gridSlot with an item needs the asset store in a bare JVM: %s" % str(e)[:120])
    # ---------------------------------------------------------------- MoveSync = the per-mod MoveSync
    MC = T("com.skyy.coretclassic.MoveSync")
    rnd = random.Random(7)
    bad = []
    for i in range(60):
        u = UUID.randomUUID()
        for k in range(rnd.randint(1, 4)):
            lay = rnd.choice(["flat", "pct"])
            sp, ju, fa = rnd.uniform(-0.5, 2), rnd.uniform(-1, 3), rnd.uniform(-0.6, 0.6)
            MV.post(u, "s%d" % k, lay, sp, ju, fa)
        s1 = [float(x) for x in MV.sums(u)]
        s2 = [float(x) for x in MC.sums(u)]          # the per-mod copy reads the SAME bridge entries
        if s1 != s2 or float(MV.speedFactor(MV.sums(u))) != float(MC.speedFactor(MC.sums(u))) \
                or float(MV.jumpForce(MV.sums(u), 11.8)) != float(MC.jumpForce(MC.sums(u), 11.8)) \
                or float(MV.fallMultiplier(MV.sums(u))) != float(MC.fallMultiplier(MC.sums(u))):
            bad.append(i)
        MV.post(u, "s0", "flat", 0.0, 0.0, 0.0)
        if MV.sources(u, False) is not None and MV.sources(u, False).containsKey("s0"):
            bad.append("remove %d" % i)
    K.eq(bad, [], "MoveSync (Core) = the per-mod MoveSync on 60 random players (sums, speed, jump, fall; zeros remove)")
    K.check(bool(MV.ownsFall("SkyyT")) and not bool(MV.ownsFall("SkyyX")) and bool(MV.ownsFall("SkyyT")), "ownsFall: first owner wins")
    MV.releaseFall("SkyyX")
    K.check(str(Core.get("stat:owner:fallDamage")) == "SkyyT", "releaseFall by another mod changes nothing")
    MV.releaseFall("SkyyT")
    K.check(Core.get("stat:owner:fallDamage") is None, "releaseFall by the owner")
    Core.put("move:proto", JClass("java.lang.Integer")(2))
    MV.checkProto("SkyyT")
    K.check(int(MV.PROTOCOL) == 1, "checkProto with another protocol only warns (PROTOCOL 1)")
    # ---------------------------------------------------------------- a module linked against Core
    Core.bridge().clear()
    r = str(T("com.skyy.coret.Use").run(pmods))
    K.check(r.startswith("1.0.1|" + A_UUID + "|1|true|a b|#") and r.endswith("|true|1|1.5"), "Use.run() (a module's calls into Core): %s" % r)
    K.save()


# =====================================================================================================================  ASM
def run_asm(out, jar, scratch, _home):
    from jpype import JClass, JArray, JObject
    K = HK.Child(out)
    srv, CL, ldr = boot()
    Sys = JClass("java.lang.System")
    mods = os.path.join(scratch, "asm_mods")
    os.makedirs(mods, exist_ok=True)
    Sys.setProperty("skyyasm.mods", mods)
    A = JClass("java.util.UUID").fromString(A_UUID)
    for run_ in (1, 2, 3):
        Sys.getProperties().remove("skyy.bridge")
        AL = ldr(ASM_JAR, CL)
        Mods = JClass("com.skyy.asmtest.Modules", loader=AL)
        Core = JClass("com.skyy.core.Core", loader=CL)
        Core.BRIDGE = None          # the fresh skyy.bridge map of this run is Core's too (one map, as on a server)
        if run_ == 1:
            Sys.clearProperty("skyyasm.betafail")
            r = str(Mods.setupAll(None, None))
            K.eq(r, "2 of 2 modules: alpha 0.1.0, beta 0.1.0", "ASM: setupAll -> both modules up")
            K.check(bool(Mods.ON[0]) and bool(Mods.ON[1]) and str(Core.get("asm:alpha")) == "up" and str(Core.get("asm:beta")) == "up",
                    "ASM: ON flags + each module's bridge key")
            br = Core.bridge()
            K.check(br.get("config:def:SkyyAsmAlpha") is not None and br.get("config:def:SkyyAsmBeta") is not None,
                    "ASM: two Server Setup sections (config:def:SkyyAsmAlpha / SkyyAsmBeta)")
            fa, fb = br.get("config:fn:SkyyAsmAlpha"), br.get("config:fn:SkyyAsmBeta")
            ra = fa.apply(JArray(JObject)(["set", "alpha.level", "6", A, "Skyy", "yes", "console"]))
            K.check(str(ra[0]) == "denied" or str(ra[0]) == "ok", "ASM: an alpha set answers (%s)" % (list(ra),))
            ra = fa.apply(JArray(JObject)(["set", "alpha.level", "6", None, "console", "yes", "console"]))
            K.check(str(ra[0]) == "ok" and int(JClass("com.skyy.asmtest.alpha.AlphaCfg", loader=AL).LEVEL) == 6, "ASM: alpha.level 6 through alpha's kit (%s)" % (list(ra),))
            JClass("com.skyy.asmtest.alpha.CfgData", loader=AL).kit().flush()
            JClass("com.skyy.asmtest.beta.CfgData", loader=AL).kit().flush()
            ap = os.path.join(mods, "Skyy_SkyyAsmTest", "alpha")
            bp = os.path.join(mods, "Skyy_SkyyAsmTest", "beta")
            K.check(os.path.isfile(os.path.join(ap, "config.properties")) and "level=6" in open(os.path.join(ap, "config.properties")).read()
                    and os.path.isfile(os.path.join(ap, "config-changes.log")), "ASM: alpha's file + change log in its own folder")
            K.check(not os.path.isfile(os.path.join(bp, "config-changes.log")), "ASM: beta's folder untouched by alpha's change")
            K.check(str(fb.apply(JArray(JObject)(["get", "beta.name"]))) == "b", "ASM: beta's kit answers its own row")
            K.check(fa.apply(JArray(JObject)(["get", "beta.name"])) is None, "ASM: alpha's kit does not know beta's row (separate sections)")
            Mods.shutdownAll(None)
            K.check(not bool(Mods.ON[0]) and not bool(Mods.ON[1]) and Core.get("asm:alpha") is None and Core.get("asm:beta") is None,
                    "ASM: shutdownAll (reverse order) stops both")
            AM1 = JClass("com.skyy.asmtest.alpha.Module", loader=AL)
            BM1 = JClass("com.skyy.asmtest.beta.Module", loader=AL)
            K.check(int(AM1.REGS) == 1 and int(BM1.BREGS) == 1 and int(AM1.ABORTS) == 0 and int(BM1.ABORTS) == 0,
                    "ASM fix2: register() ran once per module after its setup(); no abort on a clean start")
            K.check(int(AM1.SHUTS) == 1 and int(BM1.SHUTS) == 1, "ASM fix2: shutdownAll called each module's shutdown() once")
            accf = os.path.join(bp, "accounts.txt")
            K.check(os.path.isfile(accf) and open(accf, "rb").read() == b"accounts=1\n",
                    "ASM fix2: a normal stop SAVES the module's store (beta accounts.txt = accounts=1)")
        elif run_ == 2:
            Sys.setProperty("skyyasm.betafail", "1")
            Obj = JClass("java.lang.Object")
            shared, victim = Obj(), Obj()
            br = Core.bridge()
            br.put("asm:before", "kept")          # a key that existed before beta's start is never touched
            br.put("asm:shared", shared)          # another publisher's key the failed start REPLACES
            br.put("asm:victim", victim)          # another publisher's key the failed start REMOVES
            accf = os.path.join(mods, "Skyy_SkyyAsmTest", "beta", "accounts.txt")
            os.makedirs(os.path.dirname(accf), exist_ok=True)
            real = b"coins=500\nnote=the real accounts file\n"
            open(accf, "wb").write(real)
            r = str(Mods.setupAll(None, None))
            K.eq(r, "1 of 2 modules: alpha 0.1.0", "ASM: a module whose setup throws stays OFF, the other runs, nothing thrown")
            K.check(bool(Mods.ON[0]) and not bool(Mods.ON[1]), "ASM: ON = alpha only")
            BM = JClass("com.skyy.asmtest.beta.Module", loader=AL)
            K.check(int(BM.ABORTS) == 1 and int(BM.SHUTS) == 0 and BM.TIMER is None and not bool(BM.UP),
                    "ASM fix2: the failed module's abort() ran once, its shutdown() did NOT (its timer cancelled)")
            K.check(int(BM.BREGS) == 0, "ASM fix2: register() never runs when setup() threw")
            K.check(open(accf, "rb").read() == real,
                    "ASM fix2: the real data file is byte-identical after the failed start (the empty store was never saved)")
            import time as _t
            t0 = int(BM.TICKS)
            _t.sleep(0.2)
            K.check(int(BM.TICKS) == t0, "ASM fix: the failed module's scheduled tick no longer runs (%d -> %d)" % (t0, int(BM.TICKS)))
            left = sorted(str(k) for k in br.keySet() if "beta" in str(k).lower())
            K.eq(left, [], "ASM fix: every bridge key the failed start added is gone (asm:betaleak, config:*:SkyyAsmBeta)")
            K.check(str(br.get("asm:before")) == "kept" and str(br.get("asm:alpha")) == "up" and br.get("config:fn:SkyyAsmAlpha") is not None,
                    "ASM fix: keys from before and the running module's keys stay")
            sh, vi = br.get("asm:shared"), br.get("asm:victim")
            K.check(sh is not None and bool(sh.equals(shared)), "ASM fix2: a key the failed start REPLACED is restored (the same object)")
            K.check(vi is not None and bool(vi.equals(victim)), "ASM fix2: a key the failed start REMOVED is put back (the same object)")
            Mods.shutdownAll(None)
            K.check(int(BM.SHUTS) == 0 and int(BM.ABORTS) == 1, "ASM fix: shutdownAll does not stop the OFF module a second time")
            K.check(open(accf, "rb").read() == real, "ASM fix2: ... and the data file is still byte-identical after shutdownAll")
            Sys.clearProperty("skyyasm.betafail")
        else:
            # register() fails AFTER getting a registry: alpha OFF (abort, keys undone), beta runs; the line is SEVERE (engine
            # things registered before the throw stay live - the reason registrations sit in register() alone)
            Sys.setProperty("skyyasm.alpharegfail", "1")
            r = str(Mods.setupAll(None, None))
            K.eq(r, "1 of 2 modules: beta 0.1.0", "ASM fix2: a module whose register() throws stays OFF, the next module runs")
            AM = JClass("com.skyy.asmtest.alpha.Module", loader=AL)
            br = Core.bridge()
            K.check(int(AM.REGS) == 1 and int(AM.ABORTS) == 1 and int(AM.SHUTS) == 0 and not bool(Mods.ON[0]) and bool(Mods.ON[1]),
                    "ASM fix2: its abort() ran once (not shutdown()), ON = beta only")
            K.check(br.get("asm:alphareg") is None and br.get("asm:alpha") is None and br.get("config:fn:SkyyAsmAlpha") is None
                    and str(br.get("asm:beta")) == "up", "ASM fix2: the failed module's keys (setup's and register's) are gone, beta's stay")
            Mods.shutdownAll(None)
            K.check(int(AM.SHUTS) == 0, "ASM fix2: shutdownAll skips the OFF module")
            Sys.clearProperty("skyyasm.alpharegfail")
    K.save()


# =====================================================================================================================  ENGINE
def run_engine(out, jar, scratch, _home):
    import jpype
    from jpype import JClass
    K = HK.Child(out)
    boot()
    SR, SV, PI = (JClass("com.hypixel.hytale.common.semver.SemverRange"), JClass("com.hypixel.hytale.common.semver.Semver"),
                  JClass("com.hypixel.hytale.common.plugin.PluginIdentifier"))
    PM, RJR, EI, SRd = (JClass("com.hypixel.hytale.common.plugin.PluginManifest"), JClass("com.hypixel.hytale.codec.util.RawJsonReader"),
                        JClass("com.hypixel.hytale.codec.ExtraInfo"), JClass("java.io.StringReader"))
    for rs in (B.CORE_RANGE, "^1.0.0"):
        r = SR.fromString(rs)
        K.check(bool(SV.fromString("1.0.0").satisfies(r)) and bool(SV.fromString("1.9.9").satisfies(r)) and not bool(SV.fromString("2.0.0").satisfies(r))
                and not bool(SV.fromString("0.9.9").satisfies(r)), "ENGINE: range %r accepts 1.0.0 / 1.9.9, refuses 2.0.0 / 0.9.9" % rs)
        for v in ("1.0.0", "1.9.9", "2.0.0", "0.9.9"):
            K.check(bool(SV.fromString(v).satisfies(r)) == B.range_ok(rs, v), "ENGINE: skyybuild.range_ok(%r, %s) = the engine" % (rs, v))
    for nm, p in (("SkyyCore", JAR), ("SkyyAsmTest", ASM_JAR), ("SkyyCoreT", SAMPLE)):
        txt = zipfile.ZipFile(p).read("manifest.json").decode("utf-8")
        ei = EI()
        man = PM.CODEC.decodeJson(RJR(SRd(txt), jpype.JArray(jpype.JChar)(32768)), ei)
        K.eq([str(u) for u in ei.getUnknownKeys()], [], "ENGINE: %s manifest has no unknown key" % nm)
        K.eq(str(man.getName()), nm, "ENGINE: %s manifest Name is stable" % nm)
        deps = man.getDependencies()
        if nm == "SkyyCore":
            K.check(deps.isEmpty(), "ENGINE: SkyyCore has no dependency")
        else:
            rng = deps.get(PI.fromString(B.CORE_ID))
            K.check([str(k) for k in deps.keySet()] == [B.CORE_ID] and rng is not None and bool(SV.fromString(VERSION).satisfies(rng)),
                    "ENGINE: %s depends on Skyy:SkyyCore and SkyyCore %s satisfies it" % (nm, VERSION))
    K.save()


# =====================================================================================================================  PY (this process)
def py_checks():
    import skyyui as SUI
    import skyycfg as CFG
    ck = HK.check
    for rng, v, want in ((">=1.0.0 <2.0.0", "1.0.0", True), (">=1.0.0 <2.0.0", "1.4.2", True), (">=1.0.0 <2.0.0", "2.0.0", False),
                         (">=1.0.0 <2.0.0", "0.9.9", False), ("^1.0.0", "1.9.0", True), ("^1.0.0", "2.0.0", False), ("^0.1.0", "0.1.5", True),
                         ("^0.1.0", "0.2.0", False), ("~1.2.0", "1.2.9", True), ("~1.2.0", "1.3.0", False), ("1.x", "1.7.0", True),
                         ("*", "9.9.9", True), ("1.0.0 - 1.5.0", "1.5.0", True), ("=1.0.0 || =2.0.0", "2.0.0", True), (">1.0.0", "1.0.0", False)):
        ck(B.range_ok(rng, v) == want, "PY: range_ok(%r, %s) = %s" % (rng, v, want))
    try:
        B.range_ok("1.0.0", "1.0.0")
        ck(False, "PY: a bare version is refused")
    except ValueError:
        ck(True, "PY: a bare version is refused (as the engine does)")
    old = B.manifest("SkyyBank", "0.1.13", "d", "m")
    ck(json.dumps(old) == json.dumps({"Group": "Skyy", "Name": "0.1.13 SkyyBank", "Version": "0.1.13", "Description": "d", "Authors": [{"Name": "Skyy"}],
                                      "ServerVersion": "*", "DisabledByDefault": False, "IncludesAssetPack": True, "Main": "m"}),
       "PY: manifest() without the new arguments = the old manifest byte for byte")
    st = B.core_manifest("SkyyBank", "0.1.14", "d", "m", {"range": B.CORE_RANGE})
    ck(st["Name"] == "SkyyBank" and st["Dependencies"] == {"Skyy:SkyyCore": ">=1.0.0 <2.0.0"} and st["IncludesAssetPack"] is False
       and B.world_key(st) == "Skyy:SkyyBank", "PY: core_manifest = stable name + the Core dependency, no asset pack")
    ck(B.key_parts("Skyy:0.1.13 SkyyBank") == B.key_parts("Skyy:SkyyBank") == ("Skyy", "SkyyBank"), "PY: key_parts stable = versioned")
    keys = ["Skyy:0.1.12 SkyyBank", "Skyy:0.1.13 SkyyBank", "Skyy:SkyyBank", "Skyy:0.1.13 SkyyBankX", "Other:SkyyBank", "Skyy:0.1.8 SkyyParty"]
    ck(B.same_mod_keys(keys, "Skyy:SkyyBank") == ["Skyy:0.1.12 SkyyBank", "Skyy:0.1.13 SkyyBank"], "PY: same_mod_keys(stable) = the versioned keys")
    ck(B.same_mod_keys(keys, "Skyy:0.1.13 SkyyBank") == ["Skyy:0.1.12 SkyyBank", "Skyy:SkyyBank"], "PY: same_mod_keys(versioned) includes the stable key")
    jc = B.core_jar()
    ck(os.path.basename(jc) in ("SkyyCore-%s.jar" % VERSION, "SkyyCore-1.0.0.jar"), "PY: core_jar() = the SET pin (1.0.0 until 1.0.1 is pinned) or the newest built Core (%s)" % os.path.basename(jc))

    class Pool(object):
        def appendClassPath(self, p):
            raise AssertionError("must not be reached")
    try:
        B.link_core(Pool(), need="2.0.0")
        ck(False, "PY: link_core refuses a Core below the module's need")
    except SystemExit as e:
        ck("does not satisfy" in str(e), "PY: link_core refuses a Core below the module's need (%s)" % str(e)[:80])
    # skyyui: the shared HubBar differs from the per-mod one only in the owner bookkeeping
    import serverjar
    SUI.verify(assets_zip=serverjar.assets_zip(), quiet=True)
    a, b = SUI.hub_bar_java(), SUI.hub_bar_java_core()
    diff = [(x[1].split("(")[0], y[1].split("(")[0]) for x, y in zip(a, b) if x != y]
    ck(len(a) == len(b) and [d[1] for d in diff] == ["public static final java.util.Map MINE = new java.util.concurrent.ConcurrentHashMap",
                                                      "public static java.util.Map mine", "public static Object[] put",
                                                      "public static Object[] def", "public static int removeAll"],
       "PY: hub_bar_java_core differs only in MINE / mine / put / def / removeAll (%s)" % [d[1][:40] for d in diff])
    ck(all("mine()" not in s for _k, s in b), "PY: no owner-less mine() left")
    ck(SUI.core_ui_java()[:2] == SUI.java_status_methods("colorOf", "textOf"), "PY: UiKit = the kit's status methods (+ grid)")
    ck(len(CFG.CORE_TEMPLATE) == 7 and CFG.CORE_TEMPLATE[0] == "com.skyy.core.cfg.CfgRows", "PY: the 7 template names")
    with zipfile.ZipFile(JAR) as z:
        man = json.loads(z.read("manifest.json"))
        files = SUI.kit_texture_files()
        ck(man["Name"] == "SkyyCore" and man["Version"] == VERSION and "Dependencies" not in man and man["IncludesAssetPack"] is True,
           "PY: the jar's manifest: stable SkyyCore %s, no dependency, asset pack" % VERSION)
        ck(all(z.read(p) == d for p, d in files.items()) and len(files) == 59, "PY: the 59 Sky Window files = the kit's sha256 pins")
        other = [n for n in z.namelist() if not n.endswith(".class") and n != "manifest.json" and n not in files]
        ck(other == [], "PY: nothing else in the jar (%s)" % other[:3])
        for n in CFG.CORE_TEMPLATE:
            ck(n.replace(".", "/") + ".class" in z.namelist(), "PY: template %s in the jar" % n)


def tooling_checks():
    """DEPLOY / SMOKE / XC (this process + one crosscheck run): tools/deploy_set.py world keys, dependency STOPs, Core-first STOP (main
    --check on a patched SET: no write), smoke_test.apply_deploy_config on a scratch config (stable <-> versioned, CORE_RETIRES, --drop),
    tools/ci/crosscheck.py: the Core exception and every refusal around it."""
    import io, contextlib
    import deploy_set as D
    import smoke_test as SM
    ck = HK.check
    bank14 = os.path.isfile(os.path.join(ROOT, "SkyyBank", "SkyyBank-0.1.14.jar"))
    party19 = os.path.isfile(os.path.join(ROOT, "SkyyParty", "SkyyParty-0.1.9.jar"))
    ck(D.world_key_of("SkyyCore", VERSION) == "Skyy:SkyyCore", "DEPLOY: SkyyCore is enabled under Skyy:SkyyCore")
    ck(D.world_key_of("SkyyBank", "0.1.13") == "Skyy:0.1.13 SkyyBank", "DEPLOY: an old-way jar keeps its versioned key")
    if bank14 and party19:
        ck(D.world_key_of("SkyyBank", "0.1.14") == "Skyy:SkyyBank" and D.world_key_of("SkyyParty", "0.1.9") == "Skyy:SkyyParty",
           "DEPLOY: the pilots are enabled under their stable keys")
        st = D.dependency_stops([("SkyyBank", "0.1.14"), ("SkyyParty", "0.1.9")])
        ck(len(st) == 2 and all("not in SET" in w for _m, w in st), "DEPLOY: the pilots without SkyyCore STOP (%s)" % st)
        ck(D.dependency_stops([("SkyyCore", VERSION), ("SkyyBank", "0.1.14"), ("SkyyParty", "0.1.9")]) == [], "DEPLOY: with SkyyCore = no STOP")
        old = list(D.SET)
        argv = list(sys.argv)
        try:
            sys.argv = ["deploy_set.py", "--check"]
            pil = [(m, {"SkyyBank": "0.1.14", "SkyyParty": "0.1.9"}.get(m, v)) for m, v in old]
            for set_, want, what in ((pil + [("SkyyCore", VERSION)], 1, "SkyyCore pinned LAST -> STOP (it must be first)"),
                                     (pil, 1, "the pilots pinned without SkyyCore -> STOP"),
                                     ([("SkyyCore", VERSION)] + pil, 0, "SkyyCore FIRST + the pilots -> --check passes"),
                                     (old, 0, "today's SET unchanged -> --check passes")):
                D.SET = set_
                buf = io.StringIO()
                with contextlib.redirect_stdout(buf):
                    r = D.main()
                ck(r == want, "DEPLOY main --check: %s (%s; %s)" % (what, r, [l for l in buf.getvalue().splitlines() if "STOP" in l][:2]))
        finally:
            D.SET = old
            sys.argv = argv
    # smoke_test's world-config step, on a scratch config
    cfg = os.path.join(SCRATCH, "smoke_cfg.json")
    base = {"Mods": {"Skyy:0.1.12 SkyyBank": {"Enabled": False}, "Skyy:0.1.13 SkyyBank": {"Enabled": True}, "Skyy:0.1.8 SkyyParty": {"Enabled": True},
                     "Skyy:SkyyCoreProbe": {"Enabled": True}, "Skyy:SkyyDepProbe": {"Enabled": True}, "Other:Mod": {"Enabled": True}}}
    json.dump(base, open(cfg, "w"))
    SM.apply_deploy_config(cfg, ["Skyy:SkyyCore", "Skyy:SkyyBank", "Skyy:0.1.8 SkyyParty"])
    m = dict((k, v["Enabled"]) for k, v in json.load(open(cfg))["Mods"].items())
    ck(m.get("Skyy:SkyyCore") and m.get("Skyy:SkyyBank") and not m.get("Skyy:0.1.13 SkyyBank") and not m.get("Skyy:0.1.12 SkyyBank")
       and m.get("Skyy:0.1.8 SkyyParty") and m.get("Other:Mod"), "SMOKE config: Skyy:SkyyBank on, every versioned SkyyBank key off, others kept")
    ck(not m.get("Skyy:SkyyCoreProbe") and not m.get("Skyy:SkyyDepProbe"), "SMOKE config: with SkyyCore in the run the phase 0 probes go off")
    SM.apply_deploy_config(cfg, ["Skyy:0.1.13 SkyyBank"])
    m = dict((k, v["Enabled"]) for k, v in json.load(open(cfg))["Mods"].items())
    ck(m.get("Skyy:0.1.13 SkyyBank") and not m.get("Skyy:SkyyBank"), "SMOKE config: a rollback to 0.1.13 switches Skyy:SkyyBank off")
    SM.apply_deploy_config(cfg, ["Skyy:SkyyBank"], off_keys=["Skyy:SkyyCore"])
    m = dict((k, v["Enabled"]) for k, v in json.load(open(cfg))["Mods"].items())
    ck(m.get("Skyy:SkyyCore") is False and m.get("Skyy:SkyyBank"), "SMOKE config: --drop SkyyCore switches Skyy:SkyyCore off")
    # crosscheck: the Core exception and the refusals around it
    xc = [os.path.join(XC, "SkyyCore%s-0.1.0.jar" % t) for t in ("N", "W", "R", "S")] + [os.path.join(XC, "OtherPackP-0.1.0.jar")]
    if all(os.path.isfile(x) for x in xc):
        args = [sys.executable, os.path.join(ROOT, "tools", "ci", "crosscheck.py"), "--jar", JAR] + sum([["--jar", x] for x in xc], [])
        r = subprocess.run(args, capture_output=True, text=True, cwd=ROOT, errors="replace")
        out = r.stdout
        ck(r.returncode == 1 and "NOT READY" in out, "XC: crosscheck with the negative jars is NOT READY")
        ck("ACCESS SkyyCoreN com.skyy.corexn.X -> com.skyy.core.Core: class not found (it is in SkyyCore" in out
           and "Dependencies Skyy:SkyyCore" in out, "XC: calling Core WITHOUT the manifest dependency is refused")
        ck("ACCESS SkyyCoreW com.skyy.corexw.X -> com.skyy.core.cfg.CfgRows: SkyyCore's config kit TEMPLATE is not API" in out,
           "XC: naming the kit template is refused")
        ck("DEPENDENCY SkyyCoreR needs Skyy:SkyyCore >=2.0.0 <3.0.0, the set has SkyyCore 1.0.1" in out, "XC: a dependency outside Core's version is refused")
        ck("FAIL ACCESS SkyyCoreR" not in out, "XC: R's references into Core still resolve (only its range is wrong)")
        ck("core: SkyyCore 1.0.1; 2 jar(s) link against it (SkyyCoreR, SkyyCoreW)" in out, "XC: the Core line names the linked jars")
        ck("DEPENDENCY SkyyCoreS depends on Hytale:EntityModule - only Skyy:SkyyCore may be a hard dependency" in out,
           "XC fix2: a SKYY jar's non-Core dependency is still refused")
        ck("DEPENDENCY OtherPackP" not in out and "dependencies not checked (not Skyy jars): OtherPackP" in out,
           "XC fix2: a third-party jar's Dependencies (Hytale:EntityModule) are not checked and do not fail")
        ck("FAIL CONFIG" not in out, "XC fix2: no CONFIG clash in the SET + Core + negatives")


def main():
    phases = [("build", run_build), ("verifycore", run_verify_core), ("api", run_api), ("asm", run_asm), ("engine", run_engine)]
    if "--phase" in sys.argv:
        ph = HK.arg("--phase")
        try:
            if ph == "audit":
                HK.run_audit(HK.arg("--out"), HK.arg("--jar"), os.path.join(SCRATCH, "fake"))
            elif ph == "mkfake":
                HK.run_mkfake(os.path.join(SCRATCH, "fake"), HK.arg("--jar"))
            else:
                dict(phases)[ph](HK.arg("--out"), JAR, SCRATCH, None)
        except SystemExit:
            raise
        except Exception:
            import traceback
            traceback.print_exc()
            sys.exit(1)
        return
    assert os.path.isfile(JAR), JAR
    sc = os.path.realpath(SCRATCH)
    assert sc.startswith(os.path.realpath(os.path.join(ROOT, "tools", "dev", "scratch")) + os.sep), "scratch must be inside tools/dev/scratch/"
    shutil.rmtree(SCRATCH, ignore_errors=True)
    os.makedirs(os.path.join(SCRATCH, "tmp"))
    os.makedirs(os.path.join(SCRATCH, "fake"))
    env = dict(os.environ)
    env["TEMP"] = env["TMP"] = os.path.join(SCRATCH, "tmp")
    env["JAVA_TOOL_OPTIONS"] = "-XX:-UsePerfData"
    env.pop("SKYY_HARNESS_CP", None)
    os.environ["TEMP"] = os.environ["TMP"] = env["TEMP"]

    def child(label, jar=JAR, extra_cp=None):
        out = os.path.join(SCRATCH, "%s.json" % label.replace(":", "-"))
        e2 = dict(env)
        if extra_cp:
            e2["SKYY_HARNESS_CP"] = os.pathsep.join(extra_cp)
        p = subprocess.run([sys.executable, os.path.abspath(__file__), "--phase", label.split(":")[0], "--out", out, "--dir", SCRATCH,
                            "--jar", jar], env=e2)
        HK.check(p.returncode == 0, "%s: the child exited cleanly (%s)" % (label, p.returncode))
        return out
    try:
        py_checks()
        for label, _fn in phases:
            HK.take(child(label), label)
        tooling_checks()
        for lab, j, cp in (("audit:core", JAR, None), ("audit:sample", SAMPLE, [JAR]), ("audit:asm", ASM_JAR, [JAR])):
            child("mkfake", j)
            outa = child(lab, j, cp)
            if os.path.isfile(outa):
                a = json.load(open(outa))
                HK.check(not a["refused"] and a["refs"] > 50, "AA %s: engine-access audit: %d references in %d classes, refused %s"
                         % (lab, a["refs"], a["classes"], a["refused"][:5]))
                HK.check(len(a["control"]) == 1 and "sendUpdate" in a["control"][0], "AA %s: the control is refused" % lab)
                print("AA %s: %d references in %d classes, %d refused, control refused" % (lab, a["refs"], a["classes"], len(a["refused"])))
    finally:
        if "--keep" not in sys.argv:
            shutil.rmtree(SCRATCH, ignore_errors=True)
    print("SkyyCore %s harness: %d ok, %d fail(s)" % (VERSION, HK.OKS[0], len(HK.FAILS)))
    for f in HK.FAILS:
        print("FAIL:", f)
    sys.exit(1 if HK.FAILS else 0)


if __name__ == "__main__":
    main()
